/* Fitnet preloader — 3 seconds; plays once per script insertion.
   Include as the first script inside <body>. No dependencies or network assets. */
(()=>{
 if(document.getElementById('fitnet-preloader'))return;
 if(window.__fnPre && window.__fnPre.state!=='preparing')return;
 const layer=document.createElement('div');layer.id='fitnet-preloader';
 layer.setAttribute('aria-hidden','true');
 layer.style.cssText='position:fixed;inset:0;z-index:2147483647;overflow:hidden;background:#fff;pointer-events:auto;contain:strict';
 const ring=new Image(),dot=new Image();ring.src='data:image/png;base64,';dot.src='data:image/png;base64,';
 for(const im of [ring,dot]){im.style.cssText='position:absolute;display:block;max-width:none;transform-origin:50% 50%;will-change:transform';layer.append(im)}
 document.documentElement.append(layer);
 const smooth=x=>{x=Math.min(1,Math.max(0,x));return x*x*x*(x*(x*6-15)+10)};
 let raf, start, last=0;
 function draw(t){
  const w=layer.clientWidth,h=layer.clientHeight;
  const lw=w>h?Math.min(320,w/6):w/3,s=lw/1124;
  ring.style.width=lw+'px';ring.style.height=(1078*s)+'px';
  ring.style.left=(w-lw)/2+'px';ring.style.top=(h-1078*s)/2+'px';
  dot.style.width=(258*s)+'px';dot.style.height=(252*s)+'px';
  const move=smooth((t-.4)/1),x=w/2+339*s*(1-move),y=h/2+306*s*(1-move);
  dot.style.left=(x-129*s)+'px';dot.style.top=(y-126*s)+'px';
  const max=(Math.hypot(w/2,h/2)+8)/(126*s),p=Math.min(1,Math.max(0,(t-1.55)/.9));
  dot.style.transform='scale('+(1+(max-1)*p*p)+')';
  if(t>=2.45){if(window.__fnPre)window.__fnPre.reveal();layer.style.background='transparent';ring.style.visibility='hidden';
   /* A solid plane prevents raster sampling at enormous dot scales. */
   dot.style.visibility='hidden';layer.style.background='#E36F2E';
   layer.style.opacity=String(1-smooth((t-2.45)/.55));
  }
 }
 draw(0);
 function finish(){if(!layer.isConnected)return;cancelAnimationFrame(raf);layer.remove();window.dispatchEvent(new Event('fitnet:preloader-complete'))}
 window.__fnPreStop=finish;
 Promise.all([ring.decode(),dot.decode()]).then(()=>{
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}
  function tick(now){if(start===undefined)start=now;last=(now-start)/1000;
   if(last>=3){finish();return}draw(last);raf=requestAnimationFrame(tick)}
  raf=requestAnimationFrame(tick);
 }).catch(finish);
 /* Ensure a failed decode can never leave an inaccessible overlay. */
 setTimeout(finish,6000);
})();
